sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.processing = '';


    /*
     * =========================================
     * ACCEPT / REJECT TEAM REQUEST
     * =========================================
     */

    c.respond = function(
        request,
        decision
    ) {

        if (
            !request ||
            !request.sys_id
        ) {

            return;

        }


        c.processing =
            request.sys_id;


        c.server.get({

            action:
                'respond_to_request',

            requestId:
                request.sys_id,

            decision:
                decision

        }).then(

            function(response) {

                c.data =
                    response.data;


                c.processing =
                    '';

            },

            function(error) {

                console.log(
                    'My Teams request error:',
                    error
                );


                c.processing =
                    '';

            }

        );

    };

};

sp_widget.css:
/* =========================================
   CAMPUS CONNECT
   MY TEAMS
   ========================================= */

.cc-my-teams {
    max-width: 2000px;

    margin: 0 auto;

    padding: 28px 50px 24px 300px;

    color: #14213d;

    font-family: inherit;
}


/* =========================================
   PAGE HEADER
   ========================================= */

.cc-page-header {
    display: flex;

    align-items: flex-end;

    justify-content: space-between;

    gap: 25px;

    margin-bottom: 28px;
}


.cc-eyebrow {
    margin-bottom: 6px;

    color: #0066ff;

    font-size: 11px;

    font-weight: 700;

    letter-spacing: 1.4px;
}


.cc-page-header h1 {
    margin: 0 0 7px;

    color: #07152f;

    font-size: 30px;

    font-weight: 700;

    line-height: 1.2;
}


.cc-page-header p {
    margin: 0;

    color: #52627a;

    font-size: 14px;
}


/* =========================================
   CREATE BUTTON
   ========================================= */

.cc-create-btn {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    padding: 11px 18px;

    border-radius: 8px;

    background: #0066d6;

    color: #ffffff;

    font-size: 12px;

    font-weight: 700;

    text-decoration: none;

    white-space: nowrap;

    box-shadow:
        0 5px 14px rgba(0, 102, 214, .18);

    transition:
        background .18s ease,
        transform .18s ease;
}


.cc-create-btn:hover {
    background: #0055b5;

    color: #ffffff;

    text-decoration: none;

    transform: translateY(-1px);
}


/* =========================================
   SECTION TITLE
   ========================================= */

.cc-section-title {
    display: flex;

    align-items: center;

    justify-content: space-between;

    margin-bottom: 13px;
}


.cc-section-title h2 {
    margin: 0;

    color: #07152f;

    font-size: 18px;

    font-weight: 700;
}


.cc-section-title > span {
    color: #718096;

    font-size: 11px;
}


/* =========================================
   TEAM GRID
   ========================================= */

.cc-team-grid {
    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 18px;
}


/* =========================================
   TEAM CARD
   ========================================= */

.cc-team-card {
    padding: 20px;

    border: 1px solid #dfe6ef;

    border-radius: 12px;

    background: #ffffff;

    box-shadow:
        0 5px 18px rgba(7, 21, 47, .06);

    transition:
        transform .18s ease,
        box-shadow .18s ease,
        border-color .18s ease;
}


.cc-team-card:hover {
    transform: translateY(-2px);

    border-color: #cbd9e8;

    box-shadow:
        0 10px 25px rgba(7, 21, 47, .09);
}


/* =========================================
   TEAM TOP
   ========================================= */

.cc-team-top {
    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    gap: 15px;

    padding-bottom: 17px;

    border-bottom: 1px solid #edf1f5;
}


.cc-team-top h2 {
    margin: 9px 0 4px;

    color: #07152f;

    font-size: 20px;

    font-weight: 700;
}


.cc-event-name {
    margin: 0;

    color: #60718a;

    font-size: 12px;
}


.cc-team-icon {
    width: 43px;
    height: 43px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 9px;

    background: #eaf3ff;

    font-size: 21px;
}


/* =========================================
   TEAM STATUS
   ========================================= */

.cc-team-status {
    display: inline-flex;

    padding: 5px 10px;

    border-radius: 15px;

    font-size: 10px;

    font-weight: 700;

    text-transform: capitalize;
}


.team-status-open {
    color: #176d40;

    background: #e8f7ee;
}


.team-status-closed {
    color: #8d3c35;

    background: #fdebea;
}


/* =========================================
   TEAM INFORMATION
   ========================================= */

.cc-team-info {
    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 18px;

    padding: 19px 0;
}


.cc-info-label {
    display: block;

    margin-bottom: 5px;

    color: #78879a;

    font-size: 9px;

    font-weight: 700;

    letter-spacing: .6px;
}


.cc-info-item strong {
    display: block;

    color: #14213d;

    font-size: 12px;

    font-weight: 600;
}


/* =========================================
   TEAM FOOTER
   ========================================= */

.cc-team-footer {
    display: flex;

    align-items: center;

    justify-content: space-between;

    padding-top: 15px;

    border-top: 1px solid #edf1f5;
}


.cc-role-badge {
    padding: 6px 10px;

    border-radius: 15px;

    color: #075db8;

    background: #eaf3ff;

    font-size: 10px;

    font-weight: 700;
}


.cc-role-badge.member {
    color: #596a80;

    background: #f1f4f7;
}


.cc-member-note {
    color: #718096;

    font-size: 10px;
}


/* =========================================
   PENDING REQUESTS
   ========================================= */

.cc-requests-section {
    margin-top: 30px;
}


.cc-request-list {
    display: flex;

    flex-direction: column;

    gap: 10px;
}


.cc-request-card {
    display: flex;

    align-items: center;

    gap: 14px;

    padding: 14px 16px;

    border: 1px solid #dfe6ef;

    border-radius: 10px;

    background: #ffffff;

    box-shadow:
        0 3px 12px rgba(7, 21, 47, .04);
}


.cc-request-avatar {
    width: 40px;
    height: 40px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #e8f2ff;

    color: #1768bd;

    font-size: 11px;

    font-weight: 700;
}


.cc-request-content {
    flex: 1;
}


.cc-request-content h3 {
    margin: 0 0 3px;

    color: #07152f;

    font-size: 14px;

    font-weight: 700;
}


.cc-request-content p {
    margin: 0 0 4px;

    color: #60718a;

    font-size: 11px;
}


.cc-request-event {
    color: #8794a6;

    font-size: 10px;
}


.cc-request-actions {
    display: flex;

    gap: 8px;
}


.cc-accept-btn,
.cc-reject-btn {
    padding: 8px 13px;

    border-radius: 7px;

    font-size: 11px;

    font-weight: 700;

    cursor: pointer;
}


.cc-accept-btn {
    border: 1px solid #159447;

    background: #159447;

    color: #ffffff;
}


.cc-accept-btn:hover {
    background: #117b3a;
}


.cc-reject-btn {
    border: 1px solid #d4dde8;

    background: #ffffff;

    color: #3e4f65;
}


.cc-reject-btn:hover {
    background: #f5f7fa;
}


/* =========================================
   EMPTY
   ========================================= */

.cc-empty {
    padding: 55px 20px;

    text-align: center;

    border: 1px dashed #d5deea;

    border-radius: 12px;

    background: #fbfcfe;
}


.cc-empty-icon {
    width: 55px;
    height: 55px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin: 0 auto 13px;

    border-radius: 14px;

    background: #eef5ff;

    font-size: 24px;
}


.cc-empty h3 {
    margin: 0 0 7px;

    color: #07152f;

    font-size: 18px;
}


.cc-empty p {
    margin: 0 auto 20px;

    max-width: 450px;

    color: #718096;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================
   MESSAGE
   ========================================= */

.cc-message {
    margin-top: 15px;

    padding: 10px 14px;

    border-radius: 8px;

    background: #eef6ff;

    color: #1768bd;

    font-size: 11px;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 800px) {

    .cc-page-header {
        align-items: flex-start;

        flex-direction: column;
    }


    .cc-team-grid {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 600px) {

    .cc-my-teams {
        padding: 20px 14px 40px;
    }


    .cc-page-header h1 {
        font-size: 25px;
    }


    .cc-team-info {
        grid-template-columns: 1fr;
    }


    .cc-request-card {
        align-items: flex-start;

        flex-wrap: wrap;
    }


    .cc-request-actions {
        width: 100%;

        margin-left: 54px;
    }

}

sp_widget.script:
(function() {

    /*
     * =========================================
     * CAMPUS CONNECT - MY TEAMS
     * =========================================
     */

    data.teams = [];
    data.requests = [];
    data.message = '';

    var currentUser = gs.getUserID();


    /*
     * =========================================
     * CHECK CURRENT USER
     * =========================================
     */

    if (!currentUser) {
        return;
    }


    /*
     * =========================================
     * RESPOND TO JOIN REQUEST
     * =========================================
     *
     * Logged-in user = RECEIVER
     *
     * They can Accept / Reject a request
     * that belongs to them.
     */

    if (
        input &&
        input.action == 'respond_to_request'
    ) {

        var requestId =
            input.requestId;

        var decision =
            input.decision;


        if (!requestId || !decision) {

            data.message =
                'Request information is missing.';

        } else {

            var member =
                new GlideRecord(
                    'x_snc_campus_con_0_team_members'
                );


            if (!member.get(requestId)) {

                data.message =
                    'Team request not found.';

            }

            /*
             * =========================================
             * SECURITY
             * =========================================
             *
             * The request must belong to
             * the currently logged-in user.
             */

            else if (
                member.getValue('student') != currentUser
            ) {

                data.message =
                    'You are not authorized to respond to this request.';

            }


            else if (
                member.getValue('join_status') != 'Requested'
            ) {

                data.message =
                    'This request has already been processed.';

            }


            /*
             * =========================================
             * ACCEPT REQUEST
             * =========================================
             */

            else if (decision == 'accepted') {

                var teamId =
                    member.getValue('team');


                var team =
                    new GlideRecord(
                        'x_snc_campus_con_0_teams'
                    );


                if (!team.get(teamId)) {

                    data.message =
                        'The team could not be found.';

                }


                else if (
                    team.getValue('status') != 'open'
                ) {

                    data.message =
                        'This team is no longer open for joining.';

                }


                else {

                    /*
                     * Count accepted members.
                     */

                    var acceptedCountGr =
                        new GlideAggregate(
                            'x_snc_campus_con_0_team_members'
                        );


                    acceptedCountGr.addQuery(
                        'team',
                        teamId
                    );


                    acceptedCountGr.addQuery(
                        'join_status',
                        'Accepted'
                    );


                    acceptedCountGr.addAggregate(
                        'COUNT'
                    );


                    acceptedCountGr.query();


                    var acceptedCount = 0;


                    if (
                        acceptedCountGr.next()
                    ) {

                        acceptedCount =
                            parseInt(
                                acceptedCountGr.getAggregate(
                                    'COUNT'
                                ),
                                10
                            ) || 0;

                    }


                    /*
                     * Maximum team size = 5.
                     */

                    if (
                        acceptedCount >= 5
                    ) {

                        team.setValue(
                            'status',
                            'closed'
                        );

                        team.update();


                        data.message =
                            'This team is already full.';

                    }


                    else {

                        /*
                         * Accept request.
                         */

                        member.setValue(
                            'join_status',
                            'Accepted'
                        );


                        member.setValue(
                            'commitment_confirmed',
                            true
                        );


                        member.update();


                        /*
                         * Recount members.
                         */

                        var finalCountGr =
                            new GlideAggregate(
                                'x_snc_campus_con_0_team_members'
                            );


                        finalCountGr.addQuery(
                            'team',
                            teamId
                        );


                        finalCountGr.addQuery(
                            'join_status',
                            'Accepted'
                        );


                        finalCountGr.addAggregate(
                            'COUNT'
                        );


                        finalCountGr.query();


                        var finalCount = 0;


                        if (
                            finalCountGr.next()
                        ) {

                            finalCount =
                                parseInt(
                                    finalCountGr.getAggregate(
                                        'COUNT'
                                    ),
                                    10
                                ) || 0;

                        }


                        /*
                         * Close team at 5 members.
                         */

                        if (
                            finalCount >= 5
                        ) {

                            team.setValue(
                                'status',
                                'closed'
                            );

                            team.update();

                        }


                        data.message =
                            'Team request accepted successfully.';

                    }

                }

            }


            /*
             * =========================================
             * REJECT REQUEST
             * =========================================
             */

            else if (decision == 'rejected') {

                member.setValue(
                    'join_status',
                    'Rejected'
                );


                member.setValue(
                    'commitment_confirmed',
                    true
                );


                member.update();


                data.message =
                    'Team request rejected.';

            }


            else {

                data.message =
                    'Invalid request decision.';

            }

        }

    }


    /*
     * =========================================
     * GET MY TEAMS
     * =========================================
     *
     * A team belongs to the user when:
     *
     * 1. User is Team Lead
     *
     * OR
     *
     * 2. User is an Accepted Team Member
     */

    var myTeamIds = {};


    /*
     * =========================================
     * A. USER IS TEAM LEAD
     * =========================================
     */

    var leadTeams =
        new GlideRecord(
            'x_snc_campus_con_0_teams'
        );


    leadTeams.addQuery(
        'team_lead',
        currentUser
    );


    leadTeams.query();


    while (
        leadTeams.next()
    ) {

        myTeamIds[
            leadTeams.getUniqueValue()
        ] = true;

    }


    /*
     * =========================================
     * B. USER IS ACCEPTED MEMBER
     * =========================================
     */

    var memberTeams =
        new GlideRecord(
            'x_snc_campus_con_0_team_members'
        );


    memberTeams.addQuery(
        'student',
        currentUser
    );


    memberTeams.addQuery(
        'join_status',
        'Accepted'
    );


    memberTeams.query();


    while (
        memberTeams.next()
    ) {

        var memberTeamId =
            memberTeams.getValue('team');


        if (memberTeamId) {

            myTeamIds[
                memberTeamId
            ] = true;

        }

    }


    /*
     * =========================================
     * BUILD TEAM CARDS
     * =========================================
     */

    for (
        var teamId in myTeamIds
    ) {

        var teamGR =
            new GlideRecord(
                'x_snc_campus_con_0_teams'
            );


        if (
            !teamGR.get(teamId)
        ) {

            continue;

        }


        var teamData = {};


        teamData.sys_id =
            teamGR.getUniqueValue();


        teamData.teamName =
            teamGR.getDisplayValue(
                'team_name'
            );


        teamData.eventName =
            teamGR.getDisplayValue(
                'event'
            ) ||
            'Campus Event';


        teamData.teamLead =
            teamGR.getDisplayValue(
                'team_lead'
            );


        teamData.status =
            teamGR.getDisplayValue(
                'status'
            );


        teamData.statusValue =
            (
                teamGR.getValue(
                    'status'
                ) ||
                ''
            ).toLowerCase();


        teamData.formationType =
            teamGR.getDisplayValue(
                'formation_type'
            ) ||
            'Not specified';


        teamData.isLead =
            teamGR.getValue(
                'team_lead'
            ) == currentUser;


        /*
         * =========================================
         * COUNT ACCEPTED MEMBERS
         * =========================================
         */

        var countGR =
            new GlideAggregate(
                'x_snc_campus_con_0_team_members'
            );


        countGR.addQuery(
            'team',
            teamId
        );


        countGR.addQuery(
            'join_status',
            'Accepted'
        );


        countGR.addAggregate(
            'COUNT'
        );


        countGR.query();


        teamData.acceptedCount = 0;


        if (
            countGR.next()
        ) {

            teamData.acceptedCount =
                parseInt(
                    countGR.getAggregate(
                        'COUNT'
                    ),
                    10
                ) || 0;

        }


        data.teams.push(
            teamData
        );

    }





    /*
     * =========================================
     * HELPER
     * =========================================
     */

    function getInitials(name) {

        if (!name) {

            return 'ST';

        }


        var parts =
            name.trim().split(/\s+/);


        if (parts.length == 1) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }


        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();

    }


})();
